sys_script.script:
// Business Rule: Trade Book Insert Notification
// Trigger: After Insert
// Table: x_snc_trade_mana_0_trade_book
// Purpose: Trigger notification event when new trade record is created
// Uses ServiceNow's event-driven notification system

(function executeRule(current, previous /*null when async*/) {

    try {
        // Get the trade details for event parameters
        var stockName = current.stock_name || 'Unknown Stock';
        var tradeNumber = current.number || 'N/A';

        // Log the business rule execution
        gs.info('Trade Book Business Rule: Processing new trade record for ' + stockName + ' (Trade #' + tradeNumber + ')');

        // Trigger the notification event using ServiceNow's event system
        // This will be handled by the notification record we created
        // Event name: trade.book.record.inserted
        // Parameter 1: Stock Name
        // Parameter 2: Trade Number
        // Current record is automatically passed to the notification
        gs.eventQueue('trade.book.record.inserted', current, stockName, tradeNumber);

        // Log successful event trigger
        gs.info('Trade Book Event: Successfully queued notification event for ' + stockName + ' (Trade #' + tradeNumber + ')');

        // Optional: Create additional system activities if needed
        // This could include:
        // - Updating related records
        // - Triggering workflows
        // - Creating tasks or approvals
        // - Integration with external systems

        // Example: Create activity log entry
        var activity = new GlideRecord('sys_journal_field');
        activity.initialize();
        activity.element = 'activity';
        activity.element_id = current.sys_id;
        activity.table = 'x_snc_trade_mana_0_trade_book';
        activity.value = 'Trade record created and notification sent for ' + stockName + ' at buying price $' + current.buying_price + ' with stop loss $' + current.stop_loss;
        activity.insert();

    } catch (error) {
        gs.error('Error in Trade Book Insert Notification business rule: ' + error.message);
        gs.error('Stack trace: ' + error.stack);
    }

})(current, previous);
